/**
 * FeatureImportance.js - SHAP Feature Importance Display
 * Week 2 - Days 10-14
 */

import React from 'react';
import { motion } from 'framer-motion';

const FeatureImportance = ({ features }) => {
  return (
    <motion.div
      className="feature-importance-card"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, delay: 0.6 }}
    >
      <h3 className="card-title">
        <span>🔑</span>
        <span>Key Influencing Features</span>
      </h3>

      <div className="feature-list">
        {features.map((feature, index) => {
          const isPositive = feature.impact > 0;
          const absImpact = Math.abs(feature.impact);
          const maxImpact = Math.max(...features.map(f => Math.abs(f.impact)));
          const percentage = (absImpact / maxImpact) * 100;

          return (
            <motion.div
              key={feature.name}
              className="feature-item"
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.5, delay: 0.7 + index * 0.1 }}
            >
              <div className="feature-header">
                <span className="feature-name">
                  {index + 1}. {feature.name}
                </span>
                <span className={`feature-impact ${isPositive ? 'positive' : 'negative'}`}>
                  {isPositive ? '↗️ Bullish' : '↘️ Bearish'}
                </span>
              </div>

              <div className="feature-bar">
                <motion.div
                  className={`feature-bar-fill ${isPositive ? 'positive' : 'negative'}`}
                  initial={{ width: 0 }}
                  animate={{ width: `${percentage}%` }}
                  transition={{ duration: 0.8, delay: 0.8 + index * 0.1 }}
                />
              </div>

              <div style={{ fontSize: '0.75rem', color: 'var(--text-muted)', marginTop: '0.25rem' }}>
                Impact: {feature.impact.toFixed(4)}
              </div>
            </motion.div>
          );
        })}
      </div>

      <div style={{ marginTop: 'var(--spacing-md)', padding: 'var(--spacing-sm)', background: 'var(--bg-dark)', borderRadius: '8px', fontSize: '0.875rem', color: 'var(--text-muted)' }}>
        <strong>💡 Tip:</strong> Positive impacts suggest upward price movement, while negative impacts suggest downward movement.
      </div>
    </motion.div>
  );
};

export default FeatureImportance;
